script:
// Navigation helper — always sets frappe.route_options so list view
// clears saved filters instead of merging old ones with new selections.
function ndtGo(doctype, filters) {
  frappe.route_options = filters || {};
  frappe.set_route("List", doctype);
}

// Saudi time via Intl
function getSaudiParts() {
  const now   = new Date();
  const parts = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Asia/Riyadh",
    weekday: "long", month: "long", day: "numeric",
    hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: true
  }).formatToParts(now);
  const get = (type) => (parts.find(p => p.type === type) || {}).value || "";
  return {
    day:     get("day"),
    month:   get("month"),
    weekday: get("weekday"),
    hour:    parseInt(get("hour")),
  };
}

function updateClock() {
  const p         = getSaudiParts();
  const greetWord = p.hour < 12 ? "Good morning" : p.hour < 17 ? "Good afternoon" : "Good evening";
  const userName  = (frappe.session.user_fullname || frappe.session.user || "").split(" ")[0];
  const greetEl   = root_element.querySelector("#ndt-greeting");
  const monthEl   = root_element.querySelector("#ndt-cal-month");
  const dayEl     = root_element.querySelector("#ndt-cal-day");
  const weekdayEl = root_element.querySelector("#ndt-cal-weekday");
  const timeEl    = root_element.querySelector("#ndt-cal-time");

  if (greetEl)   greetEl.textContent   = greetWord + (userName ? ", " + userName : "");
  if (monthEl)   monthEl.textContent   = p.month;
  if (dayEl)     dayEl.textContent     = p.day;
  if (weekdayEl) weekdayEl.textContent = p.weekday;

  if (timeEl) {
    const timeParts = new Intl.DateTimeFormat("en-US", {
      timeZone: "Asia/Riyadh",
      hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: true
    }).formatToParts(new Date());
    const hour   = timeParts.find(p => p.type === "hour")?.value   || "00";
    const minute = timeParts.find(p => p.type === "minute")?.value || "00";
    const second = timeParts.find(p => p.type === "second")?.value || "00";
    const period = timeParts.find(p => p.type === "dayPeriod")?.value || "AM";
    timeEl.textContent = hour + ":" + minute + ":" + second + " " + period.toUpperCase();
  }
}

updateClock();
setInterval(updateClock, 1000);

// KPI card links
const now = new Date();
const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split("T")[0];
const lastOfMonth  = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split("T")[0];

const kpiCardEl1 = root_element.querySelector("#kpi-link-month");
if (kpiCardEl1) kpiCardEl1.addEventListener("click", (e) => { e.preventDefault(); ndtGo("MT Inspection", { "date_of_test": ["between", [firstOfMonth, lastOfMonth]] }); });

const kpiCardEl2 = root_element.querySelector("#kpi-link-wo");
if (kpiCardEl2) kpiCardEl2.addEventListener("click", (e) => { e.preventDefault(); ndtGo("Work Order", {}); });

const kpiCardEl3 = root_element.querySelector("#kpi-link-pending");
if (kpiCardEl3) kpiCardEl3.addEventListener("click", (e) => { e.preventDefault(); ndtGo("MT Inspection", { "docstatus": 0 }); });

const kpiCardEl4 = root_element.querySelector("#kpi-link-accepted");
if (kpiCardEl4) kpiCardEl4.addEventListener("click", (e) => { e.preventDefault(); ndtGo("MT Inspection", { "docstatus": 1, "date_of_test": ["between", [firstOfMonth, lastOfMonth]] }); });

const kpiCardEl5 = root_element.querySelector("#kpi-link-equipment");
if (kpiCardEl5) kpiCardEl5.addEventListener("click", (e) => { e.preventDefault(); ndtGo("Equipment Master", {}); });

// Shortcuts
const shortcuts = {
  "sc-new-wo":    "/app/work-order/new-work-order-1",
  "sc-new-mt":    "/app/mt-inspection/new-mt-inspection-1",
  "sc-all-mt":    "/app/mt-inspection",
  "sc-equipment": "/app/equipment-master",
  "sc-client":    "/app/client-master",
  "sc-project":   "/app/project-master"
};
Object.entries(shortcuts).forEach(([id, route]) => {
  const el = root_element.querySelector("#" + id);
  if (el) el.addEventListener("click", () => frappe.set_route(route));
});

// KPI counts
function setKPI(id, value, color) {
  const el = root_element.querySelector(id);
  if (!el) return;
  el.textContent = value;
  el.classList.remove("ndt-kpi-loading-val");
  if (color) el.style.color = color;
}

frappe.call({ method: "frappe.client.get_count", args: { doctype: "MT Inspection", filters: [["date_of_test", ">=", firstOfMonth]] }, callback: (r) => setKPI("#kpi-month", r.message ?? 0, "#2563eb") });
frappe.call({ method: "frappe.client.get_count", args: { doctype: "Work Order", filters: [] }, callback: (r) => setKPI("#kpi-wo", r.message ?? 0, "#7c3aed") });
frappe.call({
  method: "frappe.client.get_count",
  args: { doctype: "MT Inspection", filters: [["docstatus", "=", 0]] },
  callback: (r) => {
    const count = r.message ?? 0;
    setKPI("#kpi-pending", count, count > 0 ? "#d97706" : "#1e293b");
    const alertBox  = root_element.querySelector("#ndt-alert");
    const alertText = root_element.querySelector("#ndt-alert-text");
    if (count > 0 && alertBox && alertText) {
      alertText.textContent = count + " inspection" + (count > 1 ? "s" : "") + " awaiting your review.";
      alertBox.classList.add("visible");
    }
  }
});
frappe.call({ method: "frappe.client.get_count", args: { doctype: "MT Inspection", filters: [["docstatus", "=", 1], ["date_of_test", ">=", firstOfMonth]] }, callback: (r) => setKPI("#kpi-accepted", r.message ?? 0, "#10b981") });
frappe.call({ method: "frappe.client.get_count", args: { doctype: "Equipment Master" }, callback: (r) => setKPI("#kpi-equipment", r.message ?? 0, "#0891b2") });

const alertBtn = root_element.querySelector("#ndt-alert-btn");
if (alertBtn) alertBtn.addEventListener("click", () => frappe.set_route("/app/mt-inspection"));

// Recent inspections
frappe.call({
  method: "frappe.client.get_list",
  args: { doctype: "MT Inspection", fields: ["name", "date_of_test", "mt_variant", "docstatus"], order_by: "creation desc", limit: 5 },
  callback: (r) => {
    const tbody = root_element.querySelector("#ndt-recent-body");
    if (!tbody) return;
    const rows = r.message || [];
    if (!rows.length) {
      tbody.innerHTML = '<tr><td colspan="4" style="color:#60a5fa;font-size:12px;padding:12px 0;">No inspections yet</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(row => {
      const statusMap = { 0: ["Draft", "badge-draft"], 1: ["Submitted", "badge-submitted"] };
      const [label, cls] = statusMap[row.docstatus] || ["Pending", "badge-pending"];
      const date = row.date_of_test ? new Date(row.date_of_test).toLocaleDateString("en-GB") : "—";
      return `<tr onclick="frappe.set_route('/app/mt-inspection/${row.name}')">
        <td style="font-weight:600;">${row.name || "—"}</td>
        <td style="color:#64748b;">${date}</td>
        <td>${row.mt_variant || "MT"}</td>
        <td><span class="ndt-badge ${cls}">${label}</span></td>
      </tr>`;
    }).join("");
  }
});

// Branch rings
const BRANCH_COLORS = ["#2563eb","#0891b2","#7c3aed","#10b981","#f59e0b","#ef4444","#3b82f6","#06b6d4"];

function makeSVG(count, pct, color) {
  const R=48, stroke=11, W=125, cx=W/2, cy=54, circ=Math.PI*R;
  const dash = ((pct/100)*circ).toFixed(2);
  return `<svg width="${W}" height="62" viewBox="0 0 ${W} 62" style="display:block;overflow:visible;">
    <path d="M ${cx-R} ${cy} A ${R} ${R} 0 0 1 ${cx+R} ${cy}" fill="none" stroke="#dbeafe" stroke-width="${stroke}" stroke-linecap="round"/>
    <path d="M ${cx-R} ${cy} A ${R} ${R} 0 0 1 ${cx+R} ${cy}" fill="none" stroke="${color}" stroke-width="${stroke}" stroke-linecap="round"
          stroke-dasharray="0 ${circ}" style="transition:stroke-dasharray 1s cubic-bezier(0.4,0,0.2,1);"
          data-dash="${dash}" data-circ="${circ}"/>
    <text x="${cx}" y="${cy-10}" text-anchor="middle" font-family="Helvetica Neue,Arial,sans-serif" font-size="20" font-weight="700" fill="${color}">${count}</text>
    <text x="${cx}" y="${cy+6}" text-anchor="middle" font-family="Helvetica Neue,Arial,sans-serif" font-size="9" fill="#64748b">${pct}% of total</text>
  </svg>`;
}

const grid = root_element.querySelector("#ndt-branch-grid");
if (grid) {
  frappe.call({
    method: "frappe.client.get_list",
    args: { doctype: "Branch Master", fields: ["name"], limit: 50, order_by: "name asc" },
    callback: (branchRes) => {
      const branches = (branchRes.message || []).map(b => b.name);
      if (!branches.length) { grid.innerHTML = '<p style="font-size:12px;color:#64748b;margin:0;">No branches found.</p>'; return; }
      const slots = {};
      branches.forEach((name, i) => {
        const color = BRANCH_COLORS[i % BRANCH_COLORS.length];
        const wrap  = document.createElement("div");
        wrap.className = "ndt-ring-wrap";
        wrap.innerHTML = `<p class="ndt-ring-name" title="${name}">${name}</p>
          <svg width="125" height="62" viewBox="0 0 125 62" style="display:block;overflow:visible;">
            <path d="M 14 54 A 48 48 0 0 1 111 54" fill="none" stroke="#dbeafe" stroke-width="11" stroke-linecap="round"/>
          </svg>
          <p class="ndt-ring-sub">Loading...</p>`;
        wrap.addEventListener("click", () => ndtGo("MT Inspection", { branch: name }));
        grid.appendChild(wrap);
        slots[name] = { wrap, color };
      });
      frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "MT Inspection", filters: [] },
        callback: (totalRes) => {
          const total = totalRes.message || 1;
          branches.forEach(name => {
            const { wrap, color } = slots[name];
            frappe.call({
              method: "frappe.client.get_count",
              args: { doctype: "MT Inspection", filters: [["branch", "=", name]] },
              callback: (r) => {
                const count = r.message ?? 0;
                const pct   = Math.round((count / total) * 100);
                const tmp   = document.createElement("div");
                tmp.innerHTML = makeSVG(count, pct, color);
                const newSvg = tmp.querySelector("svg");
                const oldSvg = wrap.querySelector("svg");
                if (oldSvg && newSvg) wrap.replaceChild(newSvg, oldSvg);
                const sub = wrap.querySelector(".ndt-ring-sub");
                if (sub) sub.textContent = "Total inspections";
                setTimeout(() => {
                  const arc = newSvg.querySelector("path[data-dash]");
                  if (arc) arc.setAttribute("stroke-dasharray", arc.getAttribute("data-dash") + " " + arc.getAttribute("data-circ"));
                }, 150);
              }
            });
          });
        }
      });
    }
  });
}

// Calendar Modal
let currentCalendarDate = new Date();

function renderCalendar(date) {
  const year = date.getFullYear(), month = date.getMonth();
  const monthNames = ["January","February","March","April","May","June","July","August","September","October","November","December"];
  const titleEl = root_element.querySelector("#ndt-calendar-title");
  if (titleEl) titleEl.textContent = monthNames[month] + " " + year;
  const firstDay = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const daysInPrevMonth = new Date(year, month, 0).getDate();
  const today = new Date();
  const isCurrentMonth = today.getFullYear() === year && today.getMonth() === month;
  const daysContainer = root_element.querySelector("#ndt-calendar-days");
  if (!daysContainer) return;
  daysContainer.innerHTML = "";
  for (let i = firstDay - 1; i >= 0; i--) {
    const d = document.createElement("div");
    d.className = "ndt-calendar-day other-month";
    d.textContent = daysInPrevMonth - i;
    daysContainer.appendChild(d);
  }
  for (let day = 1; day <= daysInMonth; day++) {
    const d = document.createElement("div");
    d.className = "ndt-calendar-day";
    d.textContent = day;
    if (isCurrentMonth && day === today.getDate()) d.classList.add("today");
    d.addEventListener("click", function() {
      daysContainer.querySelectorAll(".ndt-calendar-day.selected").forEach(el => el.classList.remove("selected"));
      if (!d.classList.contains("today")) d.classList.add("selected");
    });
    daysContainer.appendChild(d);
  }
  const remaining = 42 - daysContainer.children.length;
  for (let day = 1; day <= remaining; day++) {
    const d = document.createElement("div");
    d.className = "ndt-calendar-day other-month";
    d.textContent = day;
    daysContainer.appendChild(d);
  }
}

const calTrigger = root_element.querySelector("#ndt-cal-widget-trigger");
const calModal   = root_element.querySelector("#ndt-calendar-modal");
const calOverlay = root_element.querySelector("#ndt-calendar-overlay");

if (calTrigger && calModal) {
  calTrigger.addEventListener("click", function() {
    currentCalendarDate = new Date();
    renderCalendar(currentCalendarDate);
    calModal.classList.add("active");
  });
}
if (calOverlay && calModal) calOverlay.addEventListener("click", () => calModal.classList.remove("active"));

const prevBtn = root_element.querySelector("#ndt-cal-prev");
const nextBtn = root_element.querySelector("#ndt-cal-next");
if (prevBtn) prevBtn.addEventListener("click", () => { currentCalendarDate.setMonth(currentCalendarDate.getMonth()-1); renderCalendar(currentCalendarDate); });
if (nextBtn) nextBtn.addEventListener("click", () => { currentCalendarDate.setMonth(currentCalendarDate.getMonth()+1); renderCalendar(currentCalendarDate); });

document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && calModal && calModal.classList.contains("active")) calModal.classList.remove("active");
});

style:
.ndt-dash {
  background: linear-gradient(135deg, #e8f0fe 0%, #dbeafe 45%, #eff6ff 100%);
  border-radius: 16px;
  padding: clamp(20px, 2.2vw, 28px);
  font-family: 'Helvetica Neue', Arial, sans-serif;
}

.ndt-dash-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: clamp(16px, 1.8vw, 22px);
  margin-bottom: clamp(14px, 1.6vw, 18px);
}

.ndt-dash-greeting {
  font-size: clamp(22px, 2.2vw, 26px);
  font-weight: 700;
  color: #1e293b;
  margin: 0 0 4px;
  letter-spacing: -0.4px;
}

.ndt-dash-sub {
  font-size: clamp(13px, 1.3vw, 15px);
  color: #64748b;
  margin: 0;
  font-weight: 500;
}

/* Calendar widget */
.ndt-cal-widget {
  background: rgba(255,255,255,0.92);
  border: 1px solid rgba(191,219,254,0.8);
  border-radius: 14px;
  overflow: hidden;
  min-width: 96px;
  text-align: center;
  box-shadow: 0 2px 12px rgba(37,99,235,0.10);
  flex-shrink: 0;
  transition: transform 0.2s cubic-bezier(0.34,1.56,0.64,1), box-shadow 0.2s ease;
}

.ndt-cal-widget:hover {
  transform: scale(1.04) translateZ(0);
  box-shadow: 0 6px 24px rgba(37,99,235,0.20);
}

.ndt-cal-month {
  background: linear-gradient(135deg, #1d4ed8, #3b82f6);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 7px 16px 6px;
}

.ndt-cal-day {
  font-size: 36px;
  font-weight: 700;
  color: #1e293b;
  line-height: 1;
  padding: 10px 16px 4px;
  letter-spacing: -1px;
}

.ndt-cal-weekday {
  font-size: clamp(10px, 1vw, 12px);
  font-weight: 600;
  color: #2563eb;
  padding: 0 16px 8px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* KPI row */
.ndt-kpi-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(clamp(140px, 15vw, 170px), 1fr));
  gap: clamp(8px, 1vw, 12px);
  margin-bottom: clamp(14px, 1.8vw, 18px);
}

.ndt-kpi-card {
  background: rgba(255,255,255,0.95);
  border: 1px solid rgba(191,219,254,0.6);
  border-radius: 12px;
  padding: clamp(12px, 1.4vw, 16px);
  cursor: pointer;
  text-decoration: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform 0.2s cubic-bezier(0.34,1.56,0.64,1), box-shadow 0.2s ease;
  min-height: clamp(82px, 8.5vw, 96px);
  position: relative;
  overflow: hidden;
  box-shadow: 0 1px 4px rgba(37,99,235,0.07);
}

.ndt-kpi-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--kpi-color, #2563eb);
  opacity: 0.7;
  border-radius: 0 0 12px 12px;
}

.ndt-kpi-card:hover {
  transform: scale(1.04) translateZ(0);
  -webkit-transform: scale(1.04) translateZ(0);
  background: #fff;
  box-shadow: 0 6px 24px rgba(37,99,235,0.16);
  text-decoration: none;
}

.ndt-kpi-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 6px;
  margin-bottom: 8px;
}

.ndt-kpi-icon {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.ndt-kpi-val {
  font-size: clamp(22px, 2.5vw, 28px);
  font-weight: 700;
  color: #1e293b;
  letter-spacing: -0.8px;
  margin: 0;
  line-height: 1;
}

.ndt-kpi-lbl {
  font-size: clamp(9px, 0.9vw, 10px);
  color: #64748b;
  margin: 0;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  line-height: 1.3;
  flex: 1;
}

.ndt-kpi-loading-val { color: #bfdbfe; }

/* Body grid */
.ndt-dash-body {
  display: grid;
  grid-template-columns: 1fr clamp(260px, 24vw, 300px);
  gap: clamp(12px, 1.4vw, 16px);
}

@media (max-width: 1200px) {
  .ndt-dash-body { grid-template-columns: 1fr; }
}

/* Glass cards */
.ndt-glass-card {
  background: rgba(255,255,255,0.95);
  border: 1px solid rgba(191,219,254,0.6);
  border-radius: 14px;
  padding: clamp(16px, 1.8vw, 22px) clamp(18px, 2vw, 24px);
  box-shadow: 0 2px 8px rgba(37,99,235,0.06);
}

.ndt-card-title {
  font-size: clamp(10px, 1vw, 11px);
  font-weight: 700;
  color: #94a3b8;
  margin: 0 0 clamp(14px, 1.6vw, 18px);
  text-transform: uppercase;
  letter-spacing: 0.9px;
}

/* Right column */
.ndt-right-col {
  display: flex;
  flex-direction: column;
  gap: clamp(10px, 1.2vw, 14px);
}

/* Alert */
.ndt-alert-glass {
  display: none;
  background: rgba(219,234,254,0.7);
  border: 1px solid rgba(147,197,253,0.5);
  border-left: 3px solid #2563eb;
  border-radius: 12px;
  padding: clamp(12px, 1.4vw, 16px) clamp(14px, 1.6vw, 18px);
}

.ndt-alert-glass.visible { display: block; }

.ndt-alert-glass-title {
  font-size: clamp(10px, 1vw, 11px);
  font-weight: 700;
  color: #1e40af;
  margin: 0 0 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.ndt-alert-glass-text {
  font-size: clamp(12px, 1.2vw, 13px);
  color: #1d4ed8;
  margin: 0 0 10px;
}

.ndt-alert-glass-btn {
  font-size: clamp(11px, 1.1vw, 12px);
  font-weight: 600;
  color: #1e40af;
  background: rgba(255,255,255,0.75);
  border: 1px solid rgba(37,99,235,0.3);
  border-radius: 6px;
  padding: clamp(5px, 0.6vw, 7px) clamp(12px, 1.4vw, 14px);
  cursor: pointer;
  width: 100%;
  transition: all 0.2s ease;
}

.ndt-alert-glass-btn:hover {
  background: #fff;
  box-shadow: 0 4px 16px rgba(37,99,235,0.18);
  transform: scale(1.02);
}

/* Shortcuts */
.ndt-shortcuts-card {
  background: rgba(255,255,255,0.95);
  border: 1px solid rgba(191,219,254,0.6);
  border-radius: 14px;
  padding: clamp(14px, 1.6vw, 18px) clamp(16px, 1.8vw, 20px);
  box-shadow: 0 2px 8px rgba(37,99,235,0.06);
}

.ndt-shortcut-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: clamp(8px, 1vw, 10px) clamp(8px, 1vw, 10px);
  margin: 0 clamp(-8px, -1vw, -10px);
  border-bottom: 1px solid rgba(219,234,254,0.5);
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease, box-shadow 0.15s ease;
}

.ndt-shortcut-item:last-child { border-bottom: none; }

.ndt-shortcut-item:hover {
  background: rgba(239,246,255,0.9);
  box-shadow: 0 2px 10px rgba(37,99,235,0.10);
}

.ndt-shortcut-label {
  font-size: clamp(12px, 1.2vw, 13px);
  font-weight: 600;
  color: #1e293b;
  margin: 0;
}

.ndt-shortcut-tag {
  font-size: clamp(9px, 0.9vw, 10px);
  font-weight: 700;
  padding: clamp(2px, 0.3vw, 3px) clamp(7px, 0.8vw, 9px);
  border-radius: 10px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.tag-new    { background: rgba(37,99,235,0.10);  color: #1d4ed8; }
.tag-all    { background: rgba(16,185,129,0.10);  color: #065f46; }
.tag-master { background: rgba(249,115,22,0.10);  color: #c2410c; }

.ndt-shortcut-arrow {
  font-size: clamp(12px, 1.1vw, 14px);
  color: #60a5fa;
  margin-left: clamp(6px, 0.7vw, 8px);
}

/* Recent table */
.ndt-recent-table { width: 100%; border-collapse: collapse; }

.ndt-recent-table th {
  font-size: clamp(9px, 0.95vw, 11px);
  font-weight: 600;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  text-align: left;
  padding: 0 0 clamp(10px, 1.2vw, 12px);
  border-bottom: 1px solid rgba(191,219,254,0.6);
}

.ndt-recent-table td {
  font-size: clamp(12px, 1.2vw, 13px);
  color: #1e293b;
  padding: clamp(9px, 1vw, 11px) 0;
  border-bottom: 1px solid rgba(219,234,254,0.4);
}

.ndt-recent-table tr:last-child td { border-bottom: none; }
.ndt-recent-table tbody tr { cursor: pointer; transition: background 0.12s; }
.ndt-recent-table tbody tr:hover td { background: rgba(239,246,255,0.6); }

.ndt-badge {
  font-size: clamp(10px, 1vw, 11px);
  font-weight: 600;
  padding: clamp(2px, 0.3vw, 3px) clamp(8px, 0.9vw, 10px);
  border-radius: 10px;
}

.badge-draft     { background: rgba(148,163,184,0.14); color: #475569; }
.badge-submitted { background: rgba(16,185,129,0.12);  color: #065f46; }
.badge-pending   { background: rgba(249,115,22,0.12);  color: #c2410c; }

/* Branch rings */
#ndt-branch-grid {
  display: flex;
  flex-wrap: wrap;
  gap: clamp(2px, 0.4vw, 4px);
  align-items: flex-start;
  justify-content: flex-start;
}

.ndt-ring-wrap {
  width: clamp(125px, 14vw, 145px);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  padding: clamp(8px, 1vw, 11px) clamp(6px, 0.8vw, 9px);
  border-radius: 12px;
  box-sizing: border-box;
  transition: transform 0.2s cubic-bezier(0.34,1.56,0.64,1), background 0.2s ease, box-shadow 0.2s ease;
  background: rgba(255,255,255,0.5);
  border: 1px solid transparent;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  -webkit-font-smoothing: antialiased;
}

.ndt-ring-wrap:hover {
  transform: scale(1.05) translateZ(0);
  -webkit-transform: scale(1.05) translateZ(0);
  background: rgba(255,255,255,0.98);
  box-shadow: 0 4px 20px rgba(37,99,235,0.14);
  border-color: rgba(191,219,254,0.8);
}

.ndt-ring-name {
  font-size: clamp(11px, 1.1vw, 12px);
  font-weight: 600;
  color: #1e293b;
  margin: 0 0 clamp(6px, 0.8vw, 8px);
  text-align: center;
  width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ndt-ring-sub {
  font-size: clamp(10px, 1vw, 11px);
  color: #64748b;
  text-align: center;
  margin: clamp(4px, 0.6vw, 6px) 0 0;
  white-space: nowrap;
}

/* Time widget */
.ndt-time-widget {
  background: rgba(255,255,255,0.92);
  border: 1px solid rgba(191,219,254,0.8);
  border-radius: 14px;
  overflow: hidden;
  min-width: 96px;
  text-align: center;
  box-shadow: 0 2px 12px rgba(37,99,235,0.10);
  flex-shrink: 0;
}

.ndt-time-display {
  font-size: 15px;
  font-weight: 700;
  color: #1e293b;
  line-height: 1.3;
  padding: 10px 14px;
  letter-spacing: 0.5px;
  font-variant-numeric: tabular-nums;
}

/* Mobile */
@media (max-width: 768px) {
  .ndt-cal-widget, .ndt-time-widget { display: none !important; }
  .ndt-dash-header { flex-direction: column; }
  .ndt-kpi-row { grid-template-columns: repeat(2, 1fr) !important; }
  .ndt-dash-body { grid-template-columns: 1fr !important; }
}

/* Calendar modal */
.ndt-calendar-modal {
  display: none;
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  z-index: 9999;
  animation: ndtFadeIn 0.2s ease-out;
}

.ndt-calendar-modal.active { display: block; }

.ndt-calendar-overlay {
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: rgba(15,23,42,0.5);
  backdrop-filter: blur(4px);
}

.ndt-calendar-popup {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 50%, #e0f2fe 100%);
  border: 1px solid rgba(255,255,255,0.9);
  border-radius: 20px;
  padding: 24px;
  box-shadow: 0 20px 60px rgba(37,99,235,0.22);
  width: 90%;
  max-width: 380px;
  animation: ndtSlideUp 0.3s cubic-bezier(0.34,1.56,0.64,1);
}

@keyframes ndtFadeIn { from { opacity: 0; } to { opacity: 1; } }

@keyframes ndtSlideUp {
  from { transform: translate(-50%, -45%); opacity: 0; }
  to   { transform: translate(-50%, -50%); opacity: 1; }
}

.ndt-calendar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.ndt-calendar-title {
  font-size: 20px;
  font-weight: 700;
  color: #1e293b;
  letter-spacing: -0.3px;
}

.ndt-calendar-nav {
  background: rgba(255,255,255,0.7);
  border: 1px solid rgba(37,99,235,0.2);
  border-radius: 8px;
  width: 36px; height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  color: #2563eb;
  cursor: pointer;
  transition: all 0.2s ease;
  font-weight: 600;
}

.ndt-calendar-nav:hover {
  background: #fff;
  border-color: #2563eb;
  transform: scale(1.08);
  box-shadow: 0 2px 8px rgba(37,99,235,0.2);
}

.ndt-calendar-weekdays {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 4px;
  margin-bottom: 8px;
}

.ndt-calendar-weekdays div {
  font-size: 11px;
  font-weight: 600;
  color: #64748b;
  text-align: center;
  padding: 8px 0;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.ndt-calendar-days {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 4px;
}

.ndt-calendar-day {
  font-size: 14px;
  font-weight: 500;
  color: #1e293b;
  text-align: center;
  padding: 9px 0;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.18s ease;
  background: rgba(255,255,255,0.45);
}

.ndt-calendar-day:hover {
  background: rgba(255,255,255,0.9);
  transform: scale(1.06);
  box-shadow: 0 2px 8px rgba(37,99,235,0.12);
}

.ndt-calendar-day.other-month { color: #93c5fd; opacity: 0.55; }

.ndt-calendar-day.today {
  background: linear-gradient(135deg, #1d4ed8, #3b82f6);
  color: #fff;
  font-weight: 700;
  box-shadow: 0 2px 12px rgba(37,99,235,0.38);
}

.ndt-calendar-day.today:hover {
  background: linear-gradient(135deg, #1e40af, #2563eb);
  transform: scale(1.08);
}

.ndt-calendar-day.selected {
  background: rgba(37,99,235,0.15);
  border: 2px solid #2563eb;
  font-weight: 700;
}

script:
/* NDT Analytics Dashboard — JS v4 Dark Edition */

function getSaudiParts() {
  var now = new Date();
  var parts = new Intl.DateTimeFormat("en-GB", {
    timeZone:"Asia/Riyadh", weekday:"long", month:"long", day:"numeric", hour:"2-digit", hour12:true
  }).formatToParts(now);
  var get = function(type){ return (parts.find(function(p){ return p.type===type; })||{}).value||""; };
  return { day:get("day"), month:get("month"), weekday:get("weekday"), hour:parseInt(get("hour")) };
}
(function setGreeting(){
  var p = getSaudiParts();
  var g = p.hour<12 ? "Good morning" : p.hour<17 ? "Good afternoon" : "Good evening";
  var u = (frappe.session.user_fullname||frappe.session.user||"").split(" ")[0];
  var el = root_element.querySelector("#nda-greeting");
  if(el) el.textContent = g+(u?", "+u:"");
  var m=root_element.querySelector("#nda-cal-month"); if(m) m.textContent=p.month;
  var d=root_element.querySelector("#nda-cal-day");   if(d) d.textContent=p.day;
  var w=root_element.querySelector("#nda-cal-weekday"); if(w) w.textContent=p.weekday;
})();

var calState = { year:new Date().getFullYear(), month:new Date().getMonth() };
var calModal   = root_element.querySelector("#nda-calendar-modal");
var calTrigger = root_element.querySelector("#nda-cal-trigger");
if(calTrigger && calModal){
  calTrigger.addEventListener("click", function(){ calModal.classList.add("nda-open"); renderCal(); });
  root_element.querySelector("#nda-calendar-overlay").addEventListener("click", function(){ calModal.classList.remove("nda-open"); });
  root_element.querySelector("#nda-cal-prev").addEventListener("click", function(){ calState.month--; if(calState.month<0){calState.month=11;calState.year--;} renderCal(); });
  root_element.querySelector("#nda-cal-next").addEventListener("click", function(){ calState.month++; if(calState.month>11){calState.month=0;calState.year++;} renderCal(); });
}
function renderCal(){
  var y=calState.year, mo=calState.month;
  var names=["January","February","March","April","May","June","July","August","September","October","November","December"];
  var t=root_element.querySelector("#nda-calendar-title"); if(t) t.textContent=names[mo]+" "+y;
  var c=root_element.querySelector("#nda-calendar-days"); if(!c) return; c.innerHTML="";
  var fd=new Date(y,mo,1).getDay(), dim=new Date(y,mo+1,0).getDate(), dp=new Date(y,mo,0).getDate();
  var now=new Date(), td=now.getDate(), tm=now.getMonth(), ty=now.getFullYear();
  for(var i=fd-1;i>=0;i--){var x=document.createElement("div");x.className="nda-cal-day-cell nda-other-month";x.textContent=dp-i;c.appendChild(x);}
  for(var d2=1;d2<=dim;d2++){var x=document.createElement("div");x.className="nda-cal-day-cell";if(d2===td&&mo===tm&&y===ty)x.classList.add("nda-today");x.textContent=d2;c.appendChild(x);}
  var rem=(7-((fd+dim)%7))%7; for(var n=1;n<=rem;n++){var x=document.createElement("div");x.className="nda-cal-day-cell nda-other-month";x.textContent=n;c.appendChild(x);}
}

var ndaState = { period:"monthly", fromDate:null, toDate:null };
var today=new Date(), fom=new Date(today.getFullYear(),today.getMonth(),1);
var fromInput=root_element.querySelector("#nda-from-date");
var toInput=root_element.querySelector("#nda-to-date");
if(fromInput){ fromInput.value=fom.toISOString().split("T")[0]; ndaState.fromDate=fromInput.value; }
if(toInput)  { toInput.value=today.toISOString().split("T")[0]; ndaState.toDate=toInput.value; }

var dpBtn=root_element.querySelector("#nda-date-picker-btn");
var dpDrop=root_element.querySelector("#nda-date-dropdown");
var dpApply=root_element.querySelector("#nda-date-apply");
var dpLabel=root_element.querySelector("#nda-date-label");
if(dpBtn&&dpDrop){
  dpBtn.addEventListener("click",function(e){ e.stopPropagation(); dpDrop.classList.toggle("nda-open"); });
  document.addEventListener("click",function(e){ if(dpDrop&&!dpDrop.contains(e.target)&&e.target!==dpBtn) dpDrop.classList.remove("nda-open"); });
}
if(dpApply){
  dpApply.addEventListener("click",function(){
    ndaState.fromDate=fromInput?fromInput.value:ndaState.fromDate;
    ndaState.toDate=toInput?toInput.value:ndaState.toDate;
    if(dpLabel&&ndaState.fromDate&&ndaState.toDate){
      var f=ndaState.fromDate.split("-"),t2=ndaState.toDate.split("-");
      dpLabel.textContent=f[2]+"/"+f[1]+" – "+t2[2]+"/"+t2[1];
    }
    if(dpDrop) dpDrop.classList.remove("nda-open");
    loadBranchRings(); loadDashboard();
  });
}

root_element.querySelectorAll(".nda-period-pill").forEach(function(b){
  b.addEventListener("click",function(){
    root_element.querySelectorAll(".nda-period-pill").forEach(function(x){ x.classList.remove("nda-active"); });
    this.classList.add("nda-active");
    ndaState.period=this.getAttribute("data-period");
    loadBranchRings(); loadDashboard();
  });
});

var nav={
  "nda-kpi-inspections":function(){ frappe.set_route("List","MT Inspection"); },
  "nda-kpi-workorders":function(){  frappe.set_route("List","Work Order"); },
  "nda-kpi-pending":function(){     frappe.set_route("List","MT Inspection",{docstatus:0}); },
  "nda-kpi-accepted":function(){    frappe.set_route("List","MT Inspection",{docstatus:1}); },
  "nda-kpi-equipment":function(){   frappe.set_route("List","Equipment Master"); },
  "nda-act-new-wo":function(){      frappe.new_doc("Work Order"); },
  "nda-act-new-mt":function(){      frappe.new_doc("MT Inspection"); },
  "nda-act-all-insp":function(){    frappe.set_route("List","MT Inspection"); },
  "nda-act-equipment":function(){   frappe.set_route("List","Equipment Master"); },
  "nda-act-clients":function(){     frappe.set_route("List","Client Master"); },
  "nda-act-projects":function(){    frappe.set_route("List","Project Master"); },
  "nda-view-all-insp":function(){   frappe.set_route("List","MT Inspection"); }
};
Object.keys(nav).forEach(function(id){
  var el=root_element.querySelector("#"+id);
  if(el) el.addEventListener("click",function(e){ e.preventDefault(); nav[id](); });
});

var RING_COLORS=["#4F6AE8","#6B8BFF","#2840D8","#8BA3FF","#1A2490","#A3B8FF","#3455CC","#7B91F0"];

function makeRingSVG(count,pct,color){
  var R=48,stroke=11,W=125,cx=W/2,cy=54,circ=Math.PI*R;
  var dash=((pct/100)*circ).toFixed(2);
  return '<svg width="'+W+'" height="62" viewBox="0 0 '+W+' 62" style="display:block;overflow:visible;">'+
    '<path d="M '+(cx-R)+' '+cy+' A '+R+' '+R+' 0 0 1 '+(cx+R)+' '+cy+'" fill="none" stroke="rgba(79,106,232,0.12)" stroke-width="'+stroke+'" stroke-linecap="round"/>'+
    '<path d="M '+(cx-R)+' '+cy+' A '+R+' '+R+' 0 0 1 '+(cx+R)+' '+cy+'" fill="none" stroke="'+color+'" stroke-width="'+stroke+'" stroke-linecap="round"'+
    ' stroke-dasharray="0 '+circ+'" style="transition:stroke-dasharray 1s cubic-bezier(0.4,0,0.2,1);"'+
    ' data-dash="'+dash+'" data-circ="'+circ+'"/>'+
    '<text x="'+cx+'" y="'+(cy-10)+'" text-anchor="middle" font-family="Syne,sans-serif" font-size="19" font-weight="800" fill="'+color+'">'+count+'</text>'+
    '<text x="'+cx+'" y="'+(cy+6)+'" text-anchor="middle" font-family="DM Mono,monospace" font-size="8" fill="#3D4F78">'+pct+'%</text>'+
  '</svg>';
}

function loadBranchRings(){
  var grid=root_element.querySelector("#nda-branch-grid");
  if(!grid) return;
  var filters=[];
  if(ndaState.fromDate) filters.push(["date_of_test",">=",ndaState.fromDate]);
  if(ndaState.toDate)   filters.push(["date_of_test","<=",ndaState.toDate]);
  frappe.call({
    method:"frappe.client.get_list",
    args:{ doctype:"Branch Master",fields:["name"],limit:50,order_by:"name asc" },
    callback:function(branchRes){
      var branches=(branchRes.message||[]).map(function(b){ return b.name; });
      if(!branches.length){ grid.innerHTML='<p style="font-size:11px;color:#3D4F78;margin:0;">No branches found.</p>'; return; }
      grid.innerHTML="";
      var slots={};
      branches.forEach(function(name,i){
        var color=RING_COLORS[i%RING_COLORS.length];
        var wrap=document.createElement("div");
        wrap.className="nda-ring-wrap";
        wrap.innerHTML='<p class="nda-ring-name" title="'+name+'">'+name+'</p>'+
          '<svg width="125" height="62" viewBox="0 0 125 62" style="display:block;overflow:visible;">'+
          '<path d="M 14 54 A 48 48 0 0 1 111 54" fill="none" stroke="rgba(79,106,232,0.1)" stroke-width="11" stroke-linecap="round"/></svg>'+
          '<p class="nda-ring-sub">Loading\u2026</p>';
        wrap.addEventListener("click",function(){ frappe.set_route("List","MT Inspection",{branch:name}); });
        grid.appendChild(wrap);
        slots[name]={ wrap:wrap, color:color };
      });
      frappe.call({
        method:"frappe.client.get_count",
        args:{ doctype:"MT Inspection", filters:filters },
        callback:function(totalRes){
          var total=totalRes.message||1;
          branches.forEach(function(name){
            var slot=slots[name];
            var bf=filters.concat([["branch","=",name]]);
            frappe.call({
              method:"frappe.client.get_count",
              args:{ doctype:"MT Inspection", filters:bf },
              callback:function(r){
                var count=r.message||0, pct=Math.round((count/total)*100);
                var tmp=document.createElement("div");
                tmp.innerHTML=makeRingSVG(count,pct,slot.color);
                var newSvg=tmp.querySelector("svg"), oldSvg=slot.wrap.querySelector("svg");
                if(oldSvg&&newSvg) slot.wrap.replaceChild(newSvg,oldSvg);
                var sub=slot.wrap.querySelector(".nda-ring-sub"); if(sub) sub.textContent="Inspections";
                setTimeout(function(){
                  var arc=newSvg.querySelector("path[data-dash]");
                  if(arc) arc.setAttribute("stroke-dasharray",arc.getAttribute("data-dash")+" "+arc.getAttribute("data-circ"));
                },150);
              }
            });
          });
        }
      });
    }
  });
}

function renderDonut(container,data,lk,vk,colors){
  container.innerHTML="";
  if(!data||!data.length){ container.innerHTML='<div class="nda-chart-loading">No data</div>'; return; }
  var total=data.reduce(function(s,d){ return s+(d[vk]||0); },0);
  if(total===0){ container.innerHTML='<div class="nda-chart-loading">No data</div>'; return; }
  var size=120,cx=size/2,cy=size/2,r=44,sw=18,circ=2*Math.PI*r,off=0;
  var svg='<svg width="'+size+'" height="'+size+'" viewBox="0 0 '+size+' '+size+'">';
  svg+='<circle cx="'+cx+'" cy="'+cy+'" r="'+r+'" fill="none" stroke="rgba(40,64,216,0.08)" stroke-width="'+sw+'"/>';
  data.forEach(function(item,i){
    var v=item[vk]||0,pct=v/total,dash=pct*circ,color=colors[i%colors.length];
    svg+='<circle class="nda-donut-segment" cx="'+cx+'" cy="'+cy+'" r="'+r+'" fill="none" stroke="'+color+'" stroke-width="'+sw+'"'+
      ' stroke-dasharray="'+dash.toFixed(2)+' '+(circ-dash).toFixed(2)+'"'+
      ' stroke-dashoffset="'+(-off).toFixed(2)+'"'+
      ' transform="rotate(-90 '+cx+' '+cy+')" style="transition:stroke-dasharray 0.8s ease;">'+
      '<title>'+(item[lk]||"")+': '+v+'</title></circle>';
    off+=dash;
  });
  svg+='</svg>';
  var wrap=document.createElement("div"); wrap.className="nda-donut-wrap";
  wrap.innerHTML=svg+'<div class="nda-donut-center"><div class="nda-donut-center-val">'+total+'</div><div class="nda-donut-center-label">Total</div></div>';
  container.appendChild(wrap);
  var leg=document.createElement("div"); leg.className="nda-donut-legend";
  data.forEach(function(item,i){
    var p=Math.round((item[vk]/total)*100);
    leg.innerHTML+='<div class="nda-legend-item"><div class="nda-legend-dot" style="background:'+colors[i%colors.length]+';"></div><span>'+(item[lk]||"—")+' · '+(item[vk]||0)+' ('+p+'%)</span></div>';
  });
  container.appendChild(leg);
}

function loadDashboard(){
  frappe.call({
    method:"alhoty.al_hoty.dashboard_api.get_dashboard_data",
    args:{ from_date:ndaState.fromDate, to_date:ndaState.toDate, period:ndaState.period },
    callback:function(r){
      if(!r.message) return;
      var d=r.message;
      setKPI("#nda-kpi-val-insp",    d.kpis.total_inspections);
      setKPI("#nda-kpi-val-wo",      d.kpis.total_work_orders);
      setKPI("#nda-kpi-val-pending", d.kpis.pending_approval);
      setKPI("#nda-kpi-val-accepted",d.kpis.accepted);
      setKPI("#nda-kpi-val-equip",   d.kpis.equipment_count);
      var mx=Math.max(d.kpis.total_inspections,d.kpis.total_work_orders,d.kpis.pending_approval,d.kpis.accepted,d.kpis.equipment_count,1);
      animBar("#nda-bar-insp",    d.kpis.total_inspections,mx);
      animBar("#nda-bar-wo",      d.kpis.total_work_orders,mx);
      animBar("#nda-bar-pending", d.kpis.pending_approval,mx);
      animBar("#nda-bar-accepted",d.kpis.accepted,mx);
      animBar("#nda-bar-equip",   d.kpis.equipment_count,mx);
      var wd=root_element.querySelector("#nda-wo-donut");
      if(wd) renderDonut(wd,d.work_order_status,"status","count",["#0E1650","#1A2490","#2840D8","#4F6AE8"]);
      var ad=root_element.querySelector("#nda-accept-donut");
      if(ad) renderDonut(ad,d.acceptance_rate,"result","count",["#4F6AE8","#0E1650"]);
      var ed=root_element.querySelector("#nda-equip-donut");
      if(ed) renderDonut(ed,d.equipment_by_type,"type","count",["#0E1650","#1A2490","#2840D8","#4F6AE8","#6B8BFF"]);
      renderTable(d.recent_inspections);
    }
  });
}
function setKPI(s,v){ var e=root_element.querySelector(s); if(!e) return; e.textContent=v; e.classList.remove("nda-loading"); }
function animBar(s,v,m){ var e=root_element.querySelector(s); if(!e) return; setTimeout(function(){ e.style.width=Math.round((v/m)*100)+"%"; },200); }
function renderTable(ins){
  var tb=root_element.querySelector("#nda-recent-body");
  if(!tb) return;
  if(!ins||!ins.length){ tb.innerHTML='<tr><td colspan="6" class="nda-table-loading">No inspections found</td></tr>'; return; }
  tb.innerHTML=ins.map(function(r){
    var sm={0:["Draft","nda-badge-draft"],1:["Submitted","nda-badge-submitted"]};
    var s=sm[r.docstatus]||["Pending","nda-badge-draft"];
    var dt=r.date_of_test?new Date(r.date_of_test).toLocaleDateString("en-GB"):"—";
    return '<tr onclick="frappe.set_route(\'/app/mt-inspection/'+r.name+'\')">'+
      '<td>'+(r.name||"—")+'</td><td>'+dt+'</td><td>'+(r.branch||"—")+'</td>'+
      '<td>'+(r.mt_variant||"MT")+'</td><td>'+(r.client||"—")+'</td>'+
      '<td><span class="nda-badge '+s[1]+'">'+s[0]+'</span></td></tr>';
  }).join("");
}

loadBranchRings();
loadDashboard();

style:
@import url('https://fonts.googleapis.com/css2?family=Syne:wght@600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700&family=DM+Mono:wght@400;500&display=swap');

/* NDT ANALYTICS DASHBOARD — LIGHT/DARK ADAPTIVE v5 */

.nda-dash {
  /* ── Light Mode (default) ── */
  --c-deep:#F0F4FF; --c-navy:#E8EEFF; --c-brand:#0E1650; --c-core:#1A2490; --c-accent:#2840D8; --c-bright:#4F6AE8; --c-electric:#2840D8;
  --glass-bg:rgba(255,255,255,0.75); --glass-border:rgba(40,64,216,0.1); --glass-hover:rgba(255,255,255,0.95);
  --glass-shadow:0 1px 20px rgba(40,64,216,0.07),0 0 0 1px rgba(40,64,216,0.06);
  --glass-hover-shadow:0 8px 32px rgba(40,64,216,0.14),0 0 0 1px rgba(40,64,216,0.12),0 0 20px rgba(40,64,216,0.08);
  --t-primary:#080E1E; --t-secondary:#48567A; --t-muted:#8C97B8; --t-accent:#2840D8;
  --ok-color:#059669; --ok-glow:rgba(5,150,105,0.1); --warn-color:#D97706; --warn-glow:rgba(217,119,6,0.1);
  --ease-spring:cubic-bezier(0.34,1.56,0.64,1); --ease-smooth:cubic-bezier(0.4,0,0.2,1);
  --radius:14px; --radius-sm:10px; --radius-xs:7px;
  background:#F0F4FF;
  background-image:radial-gradient(ellipse 80% 50% at 20% -10%,rgba(40,64,216,0.07) 0%,transparent 60%),radial-gradient(ellipse 60% 40% at 80% 90%,rgba(79,106,232,0.05) 0%,transparent 60%),radial-gradient(ellipse 40% 30% at 60% 20%,rgba(40,64,216,0.04) 0%,transparent 50%);
  border-radius:var(--radius); padding:clamp(16px,2.2vw,32px);
  font-family:'Plus Jakarta Sans',-apple-system,BlinkMacSystemFont,sans-serif;
  min-height:100%; position:relative; overflow:hidden; color:var(--t-primary);
}

/* ── Dark Mode (Frappe html[data-theme=dark] toggle) ── */
html[data-theme="dark"] .nda-dash {
  --c-deep:#060C1A; --c-navy:#0B1230; --c-brand:#0E1650; --c-core:#1A2490; --c-accent:#2840D8; --c-bright:#4F6AE8; --c-electric:#6B8BFF;
  --glass-bg:rgba(255,255,255,0.04); --glass-border:rgba(255,255,255,0.08); --glass-hover:rgba(255,255,255,0.07);
  --glass-shadow:0 1px 32px rgba(0,0,0,0.45),0 0 0 1px rgba(255,255,255,0.06);
  --glass-hover-shadow:0 8px 48px rgba(0,0,0,0.55),0 0 0 1px rgba(255,255,255,0.1),0 0 28px rgba(40,64,216,0.14);
  --t-primary:#E8EDFF; --t-secondary:#7B8DB8; --t-muted:#3D4F78; --t-accent:#8BA3FF;
  --ok-color:#34D399; --ok-glow:rgba(52,211,153,0.18); --warn-color:#F59E0B; --warn-glow:rgba(245,158,11,0.18);
  background:#060C1A;
  background-image:radial-gradient(ellipse 80% 50% at 20% -10%,rgba(40,64,216,0.16) 0%,transparent 60%),radial-gradient(ellipse 60% 40% at 80% 90%,rgba(14,22,80,0.4) 0%,transparent 60%),radial-gradient(ellipse 40% 30% at 60% 20%,rgba(79,106,232,0.07) 0%,transparent 50%);
}
.nda-bg-grid { display:none; }
.nda-bg-mesh { position:absolute; inset:0; background:radial-gradient(ellipse 120% 60% at 50% 0%,rgba(40,64,216,0.07) 0%,transparent 70%); pointer-events:none; z-index:0; }
.nda-header,.nda-kpi-row,.nda-main-row,.nda-bottom-row { position:relative; z-index:1; }

/* HEADER */
.nda-header { display:flex; align-items:center; gap:16px; margin-bottom:24px; flex-wrap:wrap; }
.nda-header-left { flex:1; min-width:200px; }
.nda-brand-tag { display:inline-flex; align-items:center; gap:5px; font-family:'DM Mono',monospace; font-size:10px; font-weight:500; color:var(--c-accent); text-transform:uppercase; letter-spacing:1.5px; background:rgba(40,64,216,0.07); border:1px solid rgba(40,64,216,0.15); border-radius:20px; padding:3px 10px 3px 8px; margin-bottom:8px; }
.nda-brand-tag::before { content:''; width:5px; height:5px; border-radius:50%; background:#34D399; box-shadow:0 0 6px #34D399; display:inline-block; animation:ndaBlink 2s ease-in-out infinite; }
.nda-greeting { font-family:'Syne',sans-serif; font-size:clamp(22px,2.6vw,34px); font-weight:800; color:var(--t-primary); margin:0 0 3px; letter-spacing:-0.8px; line-height:1.1; }
.nda-subtitle { font-size:13px; color:var(--t-secondary); margin:0; font-weight:500; }
.nda-header-center { display:flex; align-items:center; }
.nda-period-pills { display:flex; gap:4px; background:rgba(255,255,255,0.04); border:1px solid var(--glass-border); border-radius:24px; padding:4px; }
.nda-period-pill { font-family:'Plus Jakarta Sans',sans-serif; font-size:12px; font-weight:600; padding:6px 18px; border:none; border-radius:20px; background:transparent; color:var(--t-secondary); cursor:pointer; transition:all 0.18s var(--ease-smooth); }
.nda-period-pill:hover { color:var(--t-primary); background:rgba(255,255,255,0.06); }
.nda-period-pill.nda-active { background:linear-gradient(135deg,var(--c-accent),var(--c-bright)); color:#fff; box-shadow:0 2px 14px rgba(40,64,216,0.4); }
.nda-header-right { display:flex; align-items:center; gap:10px; flex-shrink:0; }
.nda-date-picker-wrap { position:relative; }
.nda-date-picker-btn { display:flex; align-items:center; gap:6px; font-family:'Plus Jakarta Sans',sans-serif; font-size:12px; font-weight:600; padding:8px 14px; border:1px solid var(--glass-border); border-radius:var(--radius-sm); background:var(--glass-bg); color:var(--t-secondary); cursor:pointer; transition:all 0.18s; backdrop-filter:blur(12px); }
.nda-date-picker-btn:hover { border-color:rgba(79,106,232,0.35); color:var(--t-primary); background:var(--glass-hover); }
.nda-date-dropdown { display:none; position:absolute; top:calc(100% + 8px); right:0; background:rgba(255,255,255,0.97); backdrop-filter:blur(24px); border:1px solid var(--glass-border); border-radius:var(--radius); padding:16px; box-shadow:0 24px 40px rgba(40,64,216,0.12),0 0 0 1px rgba(40,64,216,0.08); z-index:200; min-width:210px; }
html[data-theme="dark"] .nda-date-dropdown { background:rgba(11,18,48,0.97); box-shadow:0 24px 64px rgba(0,0,0,0.55),0 0 0 1px rgba(255,255,255,0.04); }
.nda-date-dropdown.nda-open { display:block; animation:ndaFadeUp 0.2s var(--ease-smooth); }
.nda-date-dropdown-header { margin-bottom:12px; }
.nda-date-dropdown-title { font-family:'Syne',sans-serif; font-size:13px; font-weight:700; color:var(--t-primary); }
.nda-date-field { margin-bottom:10px; }
.nda-date-field label { display:block; font-size:10px; font-weight:600; color:var(--t-muted); margin-bottom:5px; text-transform:uppercase; letter-spacing:0.8px; }
.nda-date-field input { width:100%; font-family:'DM Mono',monospace; font-size:12px; padding:8px 10px; border:1px solid var(--glass-border); border-radius:var(--radius-xs); background:rgba(40,64,216,0.04); color:var(--t-primary); outline:none; box-sizing:border-box; transition:border-color 0.18s; color-scheme:light; }
html[data-theme="dark"] .nda-date-field input { background:rgba(255,255,255,0.04); color-scheme:dark; }
.nda-date-field input:focus { border-color:rgba(79,106,232,0.5); box-shadow:0 0 12px rgba(40,64,216,0.15); }
.nda-date-apply { width:100%; padding:8px; font-family:'Plus Jakarta Sans',sans-serif; font-size:12px; font-weight:700; border:none; border-radius:var(--radius-xs); background:linear-gradient(135deg,var(--c-accent),var(--c-bright)); color:#fff; cursor:pointer; margin-top:2px; transition:all 0.18s; letter-spacing:0.3px; }
.nda-date-apply:hover { transform:translateY(-1px); box-shadow:0 4px 16px rgba(40,64,216,0.4); }
.nda-cal-widget { background:var(--glass-bg); border:1px solid var(--glass-border); border-radius:var(--radius-sm); overflow:hidden; min-width:80px; text-align:center; cursor:pointer; transition:all 0.28s var(--ease-spring); backdrop-filter:blur(12px); }
.nda-cal-widget:hover { transform:scale(1.06) translateY(-2px); box-shadow:var(--glass-hover-shadow); border-color:rgba(79,106,232,0.3); }
.nda-cal-month { background:#4F6AE8; color:rgba(255,255,255,0.95); font-family:'DM Mono',monospace; font-size:9px; font-weight:600; text-transform:uppercase; letter-spacing:1.5px; padding:5px 12px; }
html[data-theme="dark"] .nda-cal-month { background:linear-gradient(135deg,#0E1650,#2840D8); }
.nda-cal-day { font-family:'Syne',sans-serif; font-size:26px; font-weight:800; color:var(--t-primary); line-height:1; padding:8px 12px 2px; letter-spacing:-1px; }
.nda-cal-weekday { font-size:9px; font-weight:500; color:var(--t-accent); padding:0 12px 6px; text-transform:uppercase; letter-spacing:0.6px; font-family:'DM Mono',monospace; }

/* KPI */
.nda-kpi-row { display:grid; grid-template-columns:repeat(5,1fr); gap:clamp(8px,1vw,12px); margin-bottom:14px; }
.nda-kpi-card { position:relative; background:var(--glass-bg); border:1px solid var(--glass-border); border-radius:var(--radius); padding:clamp(14px,1.6vw,20px); cursor:pointer; text-decoration:none !important; display:flex; flex-direction:column; gap:10px; transition:all 0.28s var(--ease-spring); box-shadow:var(--glass-shadow); overflow:hidden; backdrop-filter:blur(16px); }
.nda-kpi-card:hover { transform:scale(1.04) translateY(-2px); box-shadow:0 6px 24px rgba(40,64,216,0.1); border-color:rgba(40,64,216,0.18); text-decoration:none !important; }
.nda-kpi-glow { display:none; }
.nda-kpi-top { display:flex; align-items:center; justify-content:space-between; }
.nda-kpi-icon { width:34px; height:34px; border-radius:var(--radius-xs); display:flex; align-items:center; justify-content:center; background:rgba(79,106,232,0.1); color:var(--c-electric); border:1px solid rgba(79,106,232,0.15); flex-shrink:0; }
.nda-kpi-trend { font-family:'DM Mono',monospace; font-size:9px; font-weight:500; color:var(--t-muted); text-transform:uppercase; letter-spacing:0.8px; background:rgba(255,255,255,0.04); border:1px solid var(--glass-border); border-radius:20px; padding:2px 7px; }
.nda-trend-ok   { color:var(--ok-color); background:var(--ok-glow); border-color:rgba(52,211,153,0.25); }
.nda-trend-warn { color:var(--warn-color); background:var(--warn-glow); border-color:rgba(245,158,11,0.25); }
.nda-kpi-value { font-family:'Syne',sans-serif; font-size:clamp(26px,3vw,36px); font-weight:800; color:var(--t-primary); letter-spacing:-1.2px; line-height:1; font-variant-numeric:tabular-nums; }
.nda-kpi-value.nda-loading { color:transparent; background:linear-gradient(90deg,rgba(40,64,216,0.07) 25%,rgba(40,64,216,0.14) 50%,rgba(40,64,216,0.07) 75%); background-size:200% 100%; animation:ndaShimmer 1.5s ease-in-out infinite; border-radius:6px; min-width:60px; min-height:36px; display:block; }
html[data-theme="dark"] .nda-kpi-value.nda-loading { background:linear-gradient(90deg,rgba(255,255,255,0.05) 25%,rgba(255,255,255,0.1) 50%,rgba(255,255,255,0.05) 75%); background-size:200% 100%; }
.nda-kpi-label { font-size:11px; font-weight:600; color:var(--t-secondary); text-transform:uppercase; letter-spacing:0.6px; margin:0; }
.nda-kpi-bar { height:3px; background:rgba(255,255,255,0.05); border-radius:4px; overflow:hidden; }
.nda-kpi-bar-fill { height:100%; border-radius:4px; background:linear-gradient(90deg,var(--c-accent),var(--c-electric)); transition:width 1.2s var(--ease-smooth); box-shadow:0 0 8px rgba(79,106,232,0.5); }
.nda-bar-ok   { background:linear-gradient(90deg,#059669,#34D399) !important; box-shadow:0 0 8px rgba(52,211,153,0.4) !important; }
.nda-bar-warn { background:linear-gradient(90deg,#D97706,#F59E0B) !important; box-shadow:0 0 8px rgba(245,158,11,0.4) !important; }

/* CARDS */
.nda-card { background:var(--glass-bg); border:1px solid var(--glass-border); border-radius:var(--radius); padding:clamp(14px,1.6vw,22px); box-shadow:var(--glass-shadow); backdrop-filter:blur(16px); position:relative; overflow:hidden; }
.nda-card::before { content:''; position:absolute; top:0; left:0; right:0; height:1px; background:linear-gradient(90deg,transparent,rgba(255,255,255,0.08),transparent); pointer-events:none; }
.nda-card-eyebrow { font-family:'DM Mono',monospace; font-size:9px; font-weight:500; color:var(--t-muted); text-transform:uppercase; letter-spacing:1.4px; margin:0 0 3px; }
.nda-card-title { font-family:'Syne',sans-serif; font-size:14px; font-weight:700; color:var(--t-primary); margin:0 0 16px; letter-spacing:-0.2px; }
.nda-card-header { display:flex; align-items:flex-start; justify-content:space-between; gap:8px; margin-bottom:4px; }
.nda-card-header .nda-card-title { margin-bottom:0; }

/* MAIN ROW */
.nda-main-row { display:grid; grid-template-columns:2fr 1fr 1fr 1fr; gap:clamp(8px,1vw,12px); margin-bottom:12px; align-items:stretch; }
.nda-chart-loading { display:flex; align-items:center; justify-content:center; min-height:160px; width:100%; color:var(--t-muted); font-size:12px; }
.nda-donut-area { min-height:180px; display:flex; flex-direction:column; align-items:center; justify-content:center; }
.nda-pulse { width:28px; height:28px; border-radius:50%; background:rgba(79,106,232,0.3); animation:ndaBlink 1.4s ease-in-out infinite; }
.nda-skeleton-row { display:flex; gap:8px; flex-wrap:wrap; }
.nda-skeleton { background:linear-gradient(90deg,rgba(40,64,216,0.06) 25%,rgba(40,64,216,0.12) 50%,rgba(40,64,216,0.06) 75%); background-size:200% 100%; animation:ndaShimmer 1.5s ease-in-out infinite; border-radius:10px; }
html[data-theme="dark"] .nda-skeleton { background:linear-gradient(90deg,rgba(255,255,255,0.04) 25%,rgba(255,255,255,0.08) 50%,rgba(255,255,255,0.04) 75%); background-size:200% 100%; }
.nda-skeleton--ring { width:120px; height:100px; }

/* Branch ring grid */
.nda-ring-grid { display:flex; flex-wrap:wrap; gap:4px; align-items:flex-start; }
.nda-ring-wrap { width:clamp(108px,12vw,128px); flex-shrink:0; display:flex; flex-direction:column; align-items:center; cursor:pointer; padding:8px 6px 6px; border-radius:var(--radius-sm); box-sizing:border-box; transition:all 0.28s var(--ease-spring); background:rgba(255,255,255,0.02); border:1px solid transparent; }
.nda-ring-wrap:hover { background:rgba(79,106,232,0.08); border-color:rgba(79,106,232,0.22); transform:translateY(-3px) scale(1.04); box-shadow:0 8px 24px rgba(0,0,0,0.35),0 0 16px rgba(40,64,216,0.15); }
.nda-ring-name { font-size:10px; font-weight:700; color:var(--t-secondary); margin:0 0 5px; text-align:center; width:100%; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; text-transform:uppercase; letter-spacing:0.4px; }
.nda-ring-sub { font-family:'DM Mono',monospace; font-size:9px; color:var(--t-muted); text-align:center; margin:3px 0 0; }

/* Donut */
.nda-donut-wrap { position:relative; width:120px; height:120px; margin:0 auto 12px; flex-shrink:0; }
.nda-donut-center { position:absolute; top:50%; left:50%; transform:translate(-50%,-50%); text-align:center; }
.nda-donut-center-val { font-family:'Syne',sans-serif; font-size:22px; font-weight:800; color:var(--t-primary); line-height:1; letter-spacing:-0.5px; }
.nda-donut-center-label { font-family:'DM Mono',monospace; font-size:8px; color:var(--t-muted); margin-top:3px; text-transform:uppercase; letter-spacing:0.8px; }
.nda-donut-segment { transition:opacity 0.18s,filter 0.18s; cursor:pointer; }
.nda-donut-segment:hover { filter:brightness(1.3) drop-shadow(0 0 6px rgba(79,106,232,0.5)); }
.nda-donut-legend { display:flex; flex-wrap:wrap; gap:5px 10px; justify-content:center; }
.nda-legend-item { display:flex; align-items:center; gap:5px; font-size:10px; color:var(--t-secondary); font-weight:500; }
.nda-legend-dot { width:6px; height:6px; border-radius:50%; flex-shrink:0; }

/* Quick actions */
.nda-main-actions { display:flex; flex-direction:column; justify-content:flex-start; overflow:visible; }
.nda-actions-grid { display:grid; grid-template-columns:1fr 1fr; gap:6px; margin-top:8px; }
.nda-action-btn { display:flex; flex-direction:column; align-items:center; justify-content:center; gap:5px; padding:10px 4px; background:rgba(255,255,255,0.6); border:1px solid rgba(40,64,216,0.1); border-radius:var(--radius-sm); cursor:pointer; font-family:'Plus Jakarta Sans',sans-serif; transition:all 0.22s var(--ease-spring); min-height:68px; width:100%; box-sizing:border-box; }
.nda-action-btn:hover { background:#fff; border-color:rgba(40,64,216,0.18); transform:scale(1.04) translateY(-2px); box-shadow:0 4px 14px rgba(40,64,216,0.08); }
.nda-action-btn:hover .nda-action-icon { background:rgba(40,64,216,0.1); box-shadow:0 0 8px rgba(79,106,232,0.2); }
.nda-action-icon { width:28px; height:28px; border-radius:var(--radius-xs); background:rgba(40,64,216,0.07); display:flex; align-items:center; justify-content:center; color:var(--c-accent); border:1px solid rgba(40,64,216,0.1); transition:all 0.18s; }
.nda-action-btn span { font-size:9px; font-weight:700; color:var(--t-secondary); text-transform:uppercase; letter-spacing:0.3px; line-height:1.3; transition:color 0.18s; text-align:center; white-space:normal; word-break:break-word; display:block; }
.nda-action-btn:hover span { color:var(--c-brand); }

/* BOTTOM ROW */
.nda-bottom-row { display:grid; grid-template-columns:clamp(200px,16vw,260px) 1fr; gap:clamp(8px,1vw,12px); }
.nda-table { width:100%; border-collapse:collapse; }
.nda-table th { font-family:'DM Mono',monospace; font-size:9px; font-weight:500; color:var(--t-muted); text-transform:uppercase; letter-spacing:0.8px; text-align:left; padding:0 10px 10px; border-bottom:1px solid rgba(255,255,255,0.05); }
.nda-table td { font-size:13px; color:var(--t-secondary); padding:11px 10px; border-bottom:1px solid rgba(255,255,255,0.03); transition:all 0.15s; }
.nda-table td:first-child { color:var(--t-primary); font-weight:700; }
.nda-table tr:last-child td { border-bottom:none; }
.nda-table tbody tr { cursor:pointer; position:relative; }
.nda-table tbody tr::after { content:''; position:absolute; left:0; top:0; bottom:0; width:2px; background:linear-gradient(180deg,var(--c-accent),var(--c-electric)); transform:scaleY(0); transition:transform 0.18s var(--ease-smooth); border-radius:0 1px 1px 0; }
.nda-table tbody tr:hover::after { transform:scaleY(1); }
.nda-table tbody tr:hover td { background:rgba(79,106,232,0.05); color:var(--t-primary); }
.nda-table-loading { color:var(--t-muted); padding:24px 0 !important; text-align:center; }
.nda-badge { font-family:'DM Mono',monospace; font-size:9px; font-weight:500; padding:3px 9px; border-radius:20px; display:inline-block; letter-spacing:0.5px; text-transform:uppercase; }
.nda-badge-draft { background:rgba(107,123,184,0.1); color:#48567A; border:1px solid rgba(107,123,184,0.2); }
.nda-badge-submitted { background:rgba(79,106,232,0.15); color:var(--c-electric); border:1px solid rgba(79,106,232,0.25); box-shadow:0 0 8px rgba(79,106,232,0.15); }
.nda-view-all { display:flex; align-items:center; gap:4px; font-size:12px; font-weight:600; color:var(--t-accent); text-decoration:none; cursor:pointer; transition:all 0.18s; white-space:nowrap; }
.nda-view-all:hover { color:var(--c-electric); gap:7px; }

/* CALENDAR MODAL */
.nda-calendar-modal { display:none; position:fixed; top:0; left:0; width:100vw; height:100vh; z-index:1050; align-items:center; justify-content:center; }
.nda-calendar-modal.nda-open { display:flex; }
.nda-calendar-overlay { position:absolute; inset:0; background:rgba(8,14,50,0.25); backdrop-filter:blur(6px); }
html[data-theme="dark"] .nda-calendar-overlay { background:rgba(6,12,26,0.75); }
.nda-calendar-popup { position:relative; background:#fff; border:1px solid rgba(40,64,216,0.12); border-radius:18px; padding:22px; box-shadow:0 16px 48px rgba(40,64,216,0.12),0 2px 8px rgba(40,64,216,0.06); min-width:300px; max-width:340px; animation:ndaFadeUp 0.25s var(--ease-smooth); }
html[data-theme="dark"] .nda-calendar-popup { background:rgba(11,18,48,0.97); border-color:rgba(255,255,255,0.08); box-shadow:0 32px 80px rgba(0,0,0,0.65); }
.nda-calendar-header { display:flex; align-items:center; justify-content:space-between; margin-bottom:18px; }
.nda-calendar-title { font-family:'Syne',sans-serif; font-size:16px; font-weight:800; color:#0E1650; }
html[data-theme="dark"] .nda-calendar-title { color:var(--t-primary); }
.nda-calendar-nav { width:30px; height:30px; border-radius:var(--radius-xs); border:1px solid rgba(40,64,216,0.15); background:rgba(40,64,216,0.05); color:#4F6AE8; font-size:12px; cursor:pointer; display:flex; align-items:center; justify-content:center; transition:all 0.18s; }
.nda-calendar-nav:hover { background:#4F6AE8; color:#fff; border-color:#4F6AE8; box-shadow:0 2px 10px rgba(79,106,232,0.3); }
html[data-theme="dark"] .nda-calendar-nav { border-color:var(--glass-border); background:var(--glass-bg); color:var(--t-secondary); }
html[data-theme="dark"] .nda-calendar-nav:hover { background:var(--c-accent); border-color:var(--c-accent); }
.nda-calendar-weekdays { display:grid; grid-template-columns:repeat(7,1fr); gap:2px; margin-bottom:6px; }
.nda-calendar-weekdays div { text-align:center; font-family:'DM Mono',monospace; font-size:9px; font-weight:600; color:#4F6AE8; text-transform:uppercase; padding:4px 0; letter-spacing:0.5px; }
html[data-theme="dark"] .nda-calendar-weekdays div { color:var(--t-muted); }
.nda-calendar-days { display:grid; grid-template-columns:repeat(7,1fr); gap:2px; }
.nda-cal-day-cell { text-align:center; padding:8px 4px; font-size:12px; font-weight:500; color:#48567A; border-radius:var(--radius-xs); cursor:pointer; transition:all 0.15s; font-variant-numeric:tabular-nums; }
.nda-cal-day-cell:hover { background:rgba(79,106,232,0.1); color:#1A2490; }
.nda-cal-day-cell.nda-today { background:#4F6AE8; color:#fff; font-weight:800; box-shadow:0 2px 10px rgba(79,106,232,0.35); }
.nda-cal-day-cell.nda-other-month { color:#C5CBDB; }
html[data-theme="dark"] .nda-cal-day-cell { color:var(--t-secondary); }
html[data-theme="dark"] .nda-cal-day-cell:hover { background:rgba(79,106,232,0.15); color:var(--t-primary); }
html[data-theme="dark"] .nda-cal-day-cell.nda-today { background:linear-gradient(135deg,#0E1650,#2840D8); box-shadow:0 0 16px rgba(40,64,216,0.35); }
html[data-theme="dark"] .nda-cal-day-cell.nda-other-month { color:var(--t-muted); opacity:0.4; }

/* RESPONSIVE */
@media (max-width:1200px) { .nda-main-row{grid-template-columns:1fr 1fr;} .nda-bottom-row{grid-template-columns:1fr;} .nda-header-center{order:3;width:100%;} }
@media (max-width:900px)  { .nda-kpi-row{grid-template-columns:repeat(2,1fr);} }
@media (max-width:768px)  { .nda-header-right{display:none;} .nda-main-row{grid-template-columns:1fr;} }
@media (max-width:480px)  { .nda-kpi-row{grid-template-columns:1fr;} }

/* ANIMATIONS */
@keyframes ndaFadeUp  { from{opacity:0;transform:translateY(16px);}  to{opacity:1;transform:translateY(0);} }
@keyframes ndaFadeIn  { from{opacity:0;} to{opacity:1;} }
@keyframes ndaShimmer { 0%{background-position:200% 0;} 100%{background-position:-200% 0;} }
@keyframes ndaBlink   { 0%,100%{transform:scale(0.9);opacity:0.6;} 50%{transform:scale(1.15);opacity:1;} }

.nda-header    { animation:ndaFadeIn 0.5s var(--ease-smooth) 0.05s both; }
.nda-kpi-card  { animation:ndaFadeIn 0.45s var(--ease-smooth) both; }
.nda-kpi-card:nth-child(1){animation-delay:0.08s;} .nda-kpi-card:nth-child(2){animation-delay:0.13s;}
.nda-kpi-card:nth-child(3){animation-delay:0.18s;} .nda-kpi-card:nth-child(4){animation-delay:0.23s;}
.nda-kpi-card:nth-child(5){animation-delay:0.28s;}
.nda-main-row  { animation:ndaFadeIn 0.5s var(--ease-smooth) 0.25s both; }
.nda-bottom-row{ animation:ndaFadeIn 0.5s var(--ease-smooth) 0.35s both; }
.nda-card      { animation:ndaFadeIn 0.5s var(--ease-smooth) 0.2s  both; }
html[data-theme="dark"] .nda-action-btn { background:rgba(255,255,255,0.02); border-color:var(--glass-border); }
html[data-theme="dark"] .nda-action-btn:hover { background:rgba(79,106,232,0.1); border-color:rgba(79,106,232,0.3); box-shadow:0 8px 24px rgba(0,0,0,0.3),0 0 16px rgba(40,64,216,0.1); }
html[data-theme="dark"] .nda-action-icon { background:rgba(79,106,232,0.1); color:var(--c-electric); border-color:rgba(79,106,232,0.15); }
